#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 _ClipRect;
UNITY_LOCATION(0) uniform mediump sampler2D _MainTex;
in mediump  vec4 vs_COLOR0;
in mediump  vec4 vs_COLOR1;
in highp  vec4 vs_TEXCOORD0;
in mediump  vec4 vs_TEXCOORD1;
in mediump  vec4 vs_TEXCOORD2;
layout(location = 0) out mediump vec4 SV_Target0;
float u_xlat0;
mediump vec4 u_xlat16_0;
vec2 u_xlat1;
mediump vec4 u_xlat16_1;
float u_xlat2;
mediump vec4 u_xlat16_2;
vec2 u_xlat3;
mediump vec2 u_xlat16_3;
int u_xlati4;
bool u_xlatb4;
float u_xlat5;
vec2 u_xlat13;
void main()
{
    u_xlat16_0.x = texture(_MainTex, vs_TEXCOORD0.xy).w;
    u_xlat5 = vs_TEXCOORD1.x;
    u_xlat0 = u_xlat5 * u_xlat16_0.x;
    u_xlat16_0.x = u_xlat0;
    u_xlat16_1.x = (-vs_TEXCOORD1.z);
    u_xlat16_1.x = u_xlat16_0.x + u_xlat16_1.x;
    u_xlat16_1.x = max(u_xlat16_1.x, 0.0);
    u_xlat16_1.x = min(u_xlat16_1.x, 1.0);
    u_xlat16_2 = (-vs_COLOR1);
    u_xlat16_2 = u_xlat16_2 + vs_COLOR0;
    u_xlat16_1 = u_xlat16_1.xxxx * u_xlat16_2;
    u_xlat16_1 = u_xlat16_1 + vs_COLOR1;
    u_xlat16_2.x = (-vs_TEXCOORD1.y);
    u_xlat16_2.x = u_xlat16_0.x + u_xlat16_2.x;
    u_xlat16_2.x = max(u_xlat16_2.x, 0.0);
    u_xlat16_2.x = min(u_xlat16_2.x, 1.0);
    u_xlat16_0 = u_xlat16_1 * u_xlat16_2.xxxx;
    u_xlat3.xy = (-_ClipRect.xy);
    u_xlat3.xy = u_xlat3.xy + _ClipRect.zw;
    u_xlat16_1.xy = (-vs_TEXCOORD2.xy);
    u_xlat16_1.xy = max(u_xlat16_1.xy, vs_TEXCOORD2.xy);
    u_xlat1.xy = u_xlat16_1.xy;
    u_xlat13.xy = (-u_xlat1.xy);
    u_xlat3.xy = u_xlat13.xy + u_xlat3.xy;
    u_xlat13.xy = vs_TEXCOORD2.zw;
    u_xlat3.xy = u_xlat13.xy * u_xlat3.xy;
    u_xlat3.xy = max(u_xlat3.xy, vec2(0.0, 0.0));
    u_xlat3.xy = min(u_xlat3.xy, vec2(1.0, 1.0));
    u_xlat16_3.xy = u_xlat3.xy;
    u_xlat16_2.x = u_xlat16_3.y * u_xlat16_3.x;
    u_xlat16_0 = u_xlat16_0 * u_xlat16_2.xxxx;
    u_xlat16_2.x = 0.00100000005;
    u_xlat16_2.x = (-u_xlat16_2.x);
    u_xlat16_2.x = u_xlat16_0.w + u_xlat16_2.x;
    u_xlat2 = u_xlat16_2.x;
    u_xlatb4 = u_xlat2<0.0;
    u_xlati4 = u_xlatb4 ? int(0xFFFFFFFFu) : int(0);
    if((u_xlati4)!=0){discard;}
    SV_Target0 = u_xlat16_0;
    return;
}
